INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 2, 'paragraph',
       $b1303${"text":"С ростом популярности майнинга все больше владельцев ASIC-оборудования задумываются о его размещении не дома, а в специализированных майнинг-отелях. Это не только помогает снизить шум и температуру в квартире, но и часто оказывается более выгодным с точки зрения энергозатрат, стабильности и безопасности. Однако выбрать подходящий хостинг – задача не из простых. Рассмотрим ключевые критерии, на которые стоит обратить внимание при выборе майнинг-отеля, а также познакомимся с рейтингом лучших хостингов России.","html":"С ростом популярности майнинга все больше владельцев ASIC-оборудования задумываются о его размещении не дома, а в специализированных майнинг-отелях. Это не только помогает снизить шум и температуру в квартире, но и часто оказывается более выгодным с точки зрения энергозатрат, стабильности и безопасности. Однако выбрать подходящий хостинг – задача не из простых. Рассмотрим ключевые критерии, на которые стоит обратить внимание при выборе майнинг-отеля, а также познакомимся с рейтингом лучших хостингов России."}$b1303$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

