INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 9, 'paragraph',
       $b1310${"text":"Известным магазином с собственным дата-центром для размещения оборудования является компания Getasic. К сожалению, бренду, как и многим другим конкурентам, не хватает подробных данных о хостинге на собственном официальном сайте. Потенциальным клиентам приходится ограничиваться скромной информацией и общими формулировками без каких-либо точных условий сотрудничества. Все, что предоставляет ресурс – это мощность отеля (40 МВт) и перечень преимуществ (официальный формат размещения, наличие основного и резервного каналов связи, удаленный контроль, наличие собственного сервисного центра).","html":"Известным магазином с собственным дата-центром для размещения оборудования является компания Getasic. К сожалению, бренду, как и многим другим конкурентам, не хватает подробных данных о хостинге на собственном официальном сайте. Потенциальным клиентам приходится ограничиваться скромной информацией и общими формулировками без каких-либо точных условий сотрудничества. Все, что предоставляет ресурс – это мощность отеля (40 МВт) и перечень преимуществ (официальный формат размещения, наличие основного и резервного каналов связи, удаленный контроль, наличие собственного сервисного центра)."}$b1310$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 10, 'paragraph',
       $b1311${"text":"Перед размещением пользователь не знает ни регион расположения хостинга, ни up-time, ни стоимость услуг. Вся эта информация предоставляется по запросу при личном общении с менеджером – фактор, способный отпугнуть многих владельцев техники для майнинга криптовалют.","html":"Перед размещением пользователь не знает ни регион расположения хостинга, ни up-time, ни стоимость услуг. Вся эта информация предоставляется по запросу при личном общении с менеджером – фактор, способный отпугнуть многих владельцев техники для майнинга криптовалют."}$b1311$::jsonb,
