INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 15, 'paragraph',
       $b1316${"text":"Список услуг магазина по продаже техники для майнинга Uminers дополняется партнерским дата-центром для размещения асиков. Располагается площадка в Красноярске, максимальная мощность составляет 20 МВт, объект готов сотрудничать с клиентами при предоставлении от 5 единиц аппаратуры мощностью не менее 5 КВт каждой. Этими значениями ограничивается вся информация о хостинге компании Uminers, что вынуждает многих потенциальных клиентов искать альтернативы.","html":"Список услуг магазина по продаже техники для майнинга Uminers дополняется партнерским дата-центром для размещения асиков. Располагается площадка в Красноярске, максимальная мощность составляет 20 МВт, объект готов сотрудничать с клиентами при предоставлении от 5 единиц аппаратуры мощностью не менее 5 КВт каждой. Этими значениями ограничивается вся информация о хостинге компании Uminers, что вынуждает многих потенциальных клиентов искать альтернативы."}$b1316$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 16, 'paragraph',
       $b1317${"text":"Магазин оборудования Uminers обладает хорошей репутацией и достаточным количеством отзывов для формирования базового представления о компании. К сожалению, этого нельзя сказать о хостинге: создается впечатление, что Uminers предоставляет услуги размещения в сопутствующем формате, делая акцент именно на продаже асиков и комплектующих.","html":"Магазин оборудования Uminers обладает хорошей репутацией и достаточным количеством отзывов для формирования базового представления о компании. К сожалению, этого нельзя сказать о хостинге: создается впечатление, что Uminers предоставляет услуги размещения в сопутствующем формате, делая акцент именно на продаже асиков и комплектующих."}$b1317$::jsonb,
