INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 21, 'paragraph',
       $b1322${"text":"Компания Mining Cluster существует с 2016 года, реализуя комплексный подход к майнингу (есть магазин и несколько дата-центров). Отзывы о сотрудничестве в целом положительные, однако их количество небольшое. На официальных ресурсах компании недостаточно информации для формирования детального представления об условиях сотрудничества. Нет данных о стоимости размещения, точном расположении хостингов (судя по опубликованной инфографике, это, вероятно, Кириши, Тула, Мурманск и Удомля), числе клиентов и асиков. Указанную информацию можно получить во время консультации с менеджером, рассказав о своих бюджетах и целях.","html":"Компания Mining Cluster существует с 2016 года, реализуя комплексный подход к майнингу (есть магазин и несколько дата-центров). Отзывы о сотрудничестве в целом положительные, однако их количество небольшое. На официальных ресурсах компании недостаточно информации для формирования детального представления об условиях сотрудничества. Нет данных о стоимости размещения, точном расположении хостингов (судя по опубликованной инфографике, это, вероятно, Кириши, Тула, Мурманск и Удомля), числе клиентов и асиков. Указанную информацию можно получить во время консультации с менеджером, рассказав о своих бюджетах и целях."}$b1322$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 22, 'paragraph',
       $b1323${"text":"Mining Cluster предлагает лизинг для юридических лиц, а также продажу готовых контейнеров, услуги сервисного центра, службу мониторинга и формат майнинга «под ключ». Заявленный up-time при размещении на хостинге Майнинг Кластер составляет 99,8%, а скорость реагирования на отключение устройства не превышает 5 минут.","html":"Mining Cluster предлагает лизинг для юридических лиц, а также продажу готовых контейнеров, услуги сервисного центра, службу мониторинга и формат майнинга «под ключ». Заявленный up-time при размещении на хостинге Майнинг Кластер составляет 99,8%, а скорость реагирования на отключение устройства не превышает 5 минут."}$b1323$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

