INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 26, 'paragraph',
       $b1327${"text":"Крупнейшая в России майнинговая компания, обладающая более чем 300-мегаваттной мощностью, что является абсолютным максимумом среди конкурентов. О масштабах деятельности BitRiver говорит тот факт, что этой организации даже удалось попасть под санкции США с формулировкой «за деятельность в технологическом секторе экономики». БитРивер располагает сразу девятью дата-центрами в разных частях России (крупнейший базируется в Братске, Иркутская область), на хостинге размещено более 100 000 устройств, а штат фирмы превышает 500 человек.","html":"Крупнейшая в России майнинговая компания, обладающая более чем 300-мегаваттной мощностью, что является абсолютным максимумом среди конкурентов. О масштабах деятельности BitRiver говорит тот факт, что этой организации даже удалось попасть под санкции США с формулировкой «за деятельность в технологическом секторе экономики». БитРивер располагает сразу девятью дата-центрами в разных частях России (крупнейший базируется в Братске, Иркутская область), на хостинге размещено более 100 000 устройств, а штат фирмы превышает 500 человек."}$b1327$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 27, 'paragraph',
       $b1328${"text":"Важно понимать, что сотрудничество с BitRiver доступно далеко не каждому: компанию интересуют только крупные майнеры, поэтому минимальный бюджет закупа оборудования составляет 5 000 000 рублей. Работа с инвесторами осуществляется индивидуально, поэтому условия размещения презентуются во время диалога с потенциальным клиентом.","html":"Важно понимать, что сотрудничество с BitRiver доступно далеко не каждому: компанию интересуют только крупные майнеры, поэтому минимальный бюджет закупа оборудования составляет 5 000 000 рублей. Работа с инвесторами осуществляется индивидуально, поэтому условия размещения презентуются во время диалога с потенциальным клиентом."}$b1328$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

