INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 32, 'paragraph',
       $b1333${"text":"Известный магазин по продаже техники для майнинга, также предлагающий услуги отеля. Intelion Data Systems имеет в собственном распоряжении сразу две площадки для размещения асиков – Тверская область (Калининская АЭС) и дата-центр АО «Тулачермет». Потенциал первого объекта составляет 32 МВт, значения для второго не приводятся. Неизвестно также количество действующих клиентов и число установленных асиков – эту информацию хостинг не предоставляет, также как и стоимость собственных услуг.","html":"Известный магазин по продаже техники для майнинга, также предлагающий услуги отеля. Intelion Data Systems имеет в собственном распоряжении сразу две площадки для размещения асиков – Тверская область (Калининская АЭС) и дата-центр АО «Тулачермет». Потенциал первого объекта составляет 32 МВт, значения для второго не приводятся. Неизвестно также количество действующих клиентов и число установленных асиков – эту информацию хостинг не предоставляет, также как и стоимость собственных услуг."}$b1333$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 33, 'paragraph',
       $b1334${"text":"Intelion Data Systems обеспечивает надежную систему охраны оборудования, up-time до 99,4%, поддержку 24/7 и возможность страхования оборудования. Кроме того, при желании клиент может записаться на экскурсию по объекту, чтобы своими глазами увидеть формат размещения.","html":"Intelion Data Systems обеспечивает надежную систему охраны оборудования, up-time до 99,4%, поддержку 24/7 и возможность страхования оборудования. Кроме того, при желании клиент может записаться на экскурсию по объекту, чтобы своими глазами увидеть формат размещения."}$b1334$::jsonb,
