INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 38, 'paragraph',
       $b1339${"text":"Компания Gis mining предлагает услуги хостинга для надежного и выгодного размещения оборудования рядом с Калининской АЭС (северная часть Тверской области). Фермы располагаются в отдельных контейнерах, соответствующим нормам безопасности Росэнергоатома. За мониторинг возгорания отвечают пожарные датчики (время реагирования специализированной пожарной части на чрезвычайные ситуации составляет 2 минуты). На территории функционирует пропускная система, количество камер наблюдения превышает 700 единиц.","html":"Компания Gis mining предлагает услуги хостинга для надежного и выгодного размещения оборудования рядом с Калининской АЭС (северная часть Тверской области). Фермы располагаются в отдельных контейнерах, соответствующим нормам безопасности Росэнергоатома. За мониторинг возгорания отвечают пожарные датчики (время реагирования специализированной пожарной части на чрезвычайные ситуации составляет 2 минуты). На территории функционирует пропускная система, количество камер наблюдения превышает 700 единиц."}$b1339$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 39, 'paragraph',
       $b1340${"text":"Gis mining заявляет не менее 99,9% up-time, удобную систему мониторинга и выгодные гарантийные условия: год бесплатного ремонта с максимальным временем решения проблемы до 10 дней (при срыве сроков предоставляется подменное оборудование). При желании клиента проводятся экскурсии на хостинге для ознакомления с условиями размещения техники.","html":"Gis mining заявляет не менее 99,9% up-time, удобную систему мониторинга и выгодные гарантийные условия: год бесплатного ремонта с максимальным временем решения проблемы до 10 дней (при срыве сроков предоставляется подменное оборудование). При желании клиента проводятся экскурсии на хостинге для ознакомления с условиями размещения техники."}$b1340$::jsonb,
