INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 44, 'paragraph',
       $b1345${"text":"Компания Umnus специализируется на комплексном подходе к майнингу в России: это значит, что здесь можно не только купить оборудование, но и разместить его на специализированных площадках. К услугам покупателей сразу четыре дата-центра в Москве, Красноярске, Иркутске и Каспийске. Суммарные производственные мощности Umnus составляют 46 МВт, обслуживанием техники занимаются специалисты собственного сервисного центра, а о защите техники заботится профессиональная система охраны с видеонаблюдением.","html":"Компания Umnus специализируется на комплексном подходе к майнингу в России: это значит, что здесь можно не только купить оборудование, но и разместить его на специализированных площадках. К услугам покупателей сразу четыре дата-центра в Москве, Красноярске, Иркутске и Каспийске. Суммарные производственные мощности Umnus составляют 46 МВт, обслуживанием техники занимаются специалисты собственного сервисного центра, а о защите техники заботится профессиональная система охраны с видеонаблюдением."}$b1345$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 45, 'paragraph',
       $b1346${"text":"Хостинг Umnus заявляет от 97,5% up-time, что несколько ниже, чем у большинства конкурентов. Однако, как показывает практика, это значение более объективное, что отмечают многие пользователи. Дата-центр предлагает два формата тарификации – фиксированная сумма за единицу техники в месяц, а также оплата по счетчику. Первый вариант предполагает бонусное техническое обслуживание асиков – услуга уже включена в стоимость.","html":"Хостинг Umnus заявляет от 97,5% up-time, что несколько ниже, чем у большинства конкурентов. Однако, как показывает практика, это значение более объективное, что отмечают многие пользователи. Дата-центр предлагает два формата тарификации – фиксированная сумма за единицу техники в месяц, а также оплата по счетчику. Первый вариант предполагает бонусное техническое обслуживание асиков – услуга уже включена в стоимость."}$b1346$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

