INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 50, 'paragraph',
       $b1351${"text":"Магазин техники и хостинг Sibmain представляет собой один из самых мощных отелей для майнинга в России – объем составляет 80 МВт. Располагаясь в Красноярске, дата-центр предлагает полный перечень услуг, начиная от экскурсий и заканчивая работой специалистов сервисного центра. Заявленный up-time составляет 99%, а время реагирования на отключение асиков не превышает 7 минут.","html":"Магазин техники и хостинг Sibmain представляет собой один из самых мощных отелей для майнинга в России – объем составляет 80 МВт. Располагаясь в Красноярске, дата-центр предлагает полный перечень услуг, начиная от экскурсий и заканчивая работой специалистов сервисного центра. Заявленный up-time составляет 99%, а время реагирования на отключение асиков не превышает 7 минут."}$b1351$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 51, 'paragraph',
       $b1352${"text":"Охрана объекта круглосуточная, имеется система удаленного контроля и фильтры для воздуха. Тарификация основывается на стоимости за электричество в зависимости от времени суток: дневной тариф – от 5 рублей за КВт, ночной тариф – от 4 рублей за КВт (16 часов в будни, 24 часа в выходные и праздники). Sibmain гарантирует возмещение стоимости утраты оборудования, если причиной станет вина сотрудников хостинга.","html":"Охрана объекта круглосуточная, имеется система удаленного контроля и фильтры для воздуха. Тарификация основывается на стоимости за электричество в зависимости от времени суток: дневной тариф – от 5 рублей за КВт, ночной тариф – от 4 рублей за КВт (16 часов в будни, 24 часа в выходные и праздники). Sibmain гарантирует возмещение стоимости утраты оборудования, если причиной станет вина сотрудников хостинга."}$b1352$::jsonb,
