INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 56, 'paragraph',
       $b1357${"text":"Крупная группа компаний, предоставляющая услуги как в области продажи оборудования, так и размещения устройств для майнинга. IBMM Technology предлагает сразу пять вариантов запуска аппаратуры клиентов в самых разных частях России: Минеральные Воды, Пермь, Пенза, Иркутск и Бурятия. Стоимость услуг хостинга стартует с отметки 4.2 рубля за КВт – такой тариф доступен при передаче в работу внушительного парка асиков, от 50 единиц. Минимальный объем фермы для сотрудничества с IBMM Technology составляет 5 единиц.","html":"Крупная группа компаний, предоставляющая услуги как в области продажи оборудования, так и размещения устройств для майнинга. IBMM Technology предлагает сразу пять вариантов запуска аппаратуры клиентов в самых разных частях России: Минеральные Воды, Пермь, Пенза, Иркутск и Бурятия. Стоимость услуг хостинга стартует с отметки 4.2 рубля за КВт – такой тариф доступен при передаче в работу внушительного парка асиков, от 50 единиц. Минимальный объем фермы для сотрудничества с IBMM Technology составляет 5 единиц."}$b1357$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 57, 'paragraph',
       $b1358${"text":"К сожалению, далеко не вся подробная информация о хостинге представлена на официальном сайте площадки – подробности предлагается узнавать во время непосредственного общения с менеджерами. Известно, что асики клиентов располагаются в помещении, есть надежная система охраны, сотрудничество оформляется официально. На текущий момент объемы размещения IBMM Technology составляют порядка 4 000 единиц техники клиентов.","html":"К сожалению, далеко не вся подробная информация о хостинге представлена на официальном сайте площадки – подробности предлагается узнавать во время непосредственного общения с менеджерами. Известно, что асики клиентов располагаются в помещении, есть надежная система охраны, сотрудничество оформляется официально. На текущий момент объемы размещения IBMM Technology составляют порядка 4 000 единиц техники клиентов."}$b1358$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

