INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 62, 'paragraph',
       $b1363${"text":"Один из крупнейших магазинов по продаже оборудования для майнинга в России предоставляет также услуги дата-центра для размещения техники клиентов. К сожалению, по непонятным причинам на сайте компании нет подробной информации об условиях размещения аппаратуры. Promminer лишь утверждает, что предоставляет одну из минимальных цен на размещение (от 5,2 рублей за КВт), однако на практике – это далеко не самое выгодное предложение среди конкурентов. Заявленный up-time стандартный – 99%, обслуживание осуществляется круглосуточно 7 дней в неделю, обозначена система онлайн-мониторинга. Среди ярких преимуществ хостинга Promminer – страхование техники клиентов и охрана объекта Росгвардией.","html":"Один из крупнейших магазинов по продаже оборудования для майнинга в России предоставляет также услуги дата-центра для размещения техники клиентов. К сожалению, по непонятным причинам на сайте компании нет подробной информации об условиях размещения аппаратуры. Promminer лишь утверждает, что предоставляет одну из минимальных цен на размещение (от 5,2 рублей за КВт), однако на практике – это далеко не самое выгодное предложение среди конкурентов. Заявленный up-time стандартный – 99%, обслуживание осуществляется круглосуточно 7 дней в неделю, обозначена система онлайн-мониторинга. Среди ярких преимуществ хостинга Promminer – страхование техники клиентов и охрана объекта Росгвардией."}$b1363$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 63, 'paragraph',
       $b1364${"text":"При более детальном изучении площадки становится ясно, что на сайте присутствует обзорное видео с обзором хостинга. Ролик позволяет понять, что отель располагается в Кемеровской области, а стоимость размещения начинается с отметки 4,3 рубля за КВт (несоответствие цифрам на сайте). Подобная политика выглядит, как минимум, странной.","html":"При более детальном изучении площадки становится ясно, что на сайте присутствует обзорное видео с обзором хостинга. Ролик позволяет понять, что отель располагается в Кемеровской области, а стоимость размещения начинается с отметки 4,3 рубля за КВт (несоответствие цифрам на сайте). Подобная политика выглядит, как минимум, странной."}$b1364$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-majning-otel-top-10-hostingov-dlya-majninga';

