SELECT a.id, 24, 'paragraph',
       $b1401${"text":"Финальное место в нашем рейтинге занимает профильный кошелек для работы с блокчейном The Open Network (TON). Все дело в том, что многие аналитики пророчат этой системе впечатляющее будущее, а сама монета Toncoin уже листится на большинстве бирж и участвует в разнообразных проектах. Экосистема стремительно развивается, следовательно, о надежном хранении актива также необходимо позаботиться – это именно горячий Tonkeeper.","html":"Финальное место в нашем рейтинге занимает профильный кошелек для работы с блокчейном The Open Network (TON). Все дело в том, что многие аналитики пророчат этой системе впечатляющее будущее, а сама монета Toncoin уже листится на большинстве бирж и участвует в разнообразных проектах. Экосистема стремительно развивается, следовательно, о надежном хранении актива также необходимо позаботиться – это именно горячий Tonkeeper."}$b1401$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 25, 'paragraph',
       $b1402${"text":"Кошелек Tonkeeper молод, однако это не помешало инструменту стать №1 в профильном блокчейне. Пользователю доступны функции обмена, стейкинга, работы с NFT. Кошелек обладает собственным браузером, скорость работы высокая, а собственная система авторизации в дружественных сервисах проста и понятна.","html":"Кошелек Tonkeeper молод, однако это не помешало инструменту стать №1 в профильном блокчейне. Пользователю доступны функции обмена, стейкинга, работы с NFT. Кошелек обладает собственным браузером, скорость работы высокая, а собственная система авторизации в дружественных сервисах проста и понятна."}$b1402$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

