INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 30, 'paragraph',
       $b1407${"text":"Еще один старый и проверенный кошелек: CoinPayments поддерживает более 2 000 криптовалют, поэтому недостатка в диверсификации пользователи не испытывают. Помимо классической функции обмена доступен интересный инструмент «Сейф», позволяющий замораживать часть актива по принципу «холодного» кошелька – это дополнительная защита цифровых активов.","html":"Еще один старый и проверенный кошелек: CoinPayments поддерживает более 2 000 криптовалют, поэтому недостатка в диверсификации пользователи не испытывают. Помимо классической функции обмена доступен интересный инструмент «Сейф», позволяющий замораживать часть актива по принципу «холодного» кошелька – это дополнительная защита цифровых активов."}$b1407$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 31, 'paragraph',
       $b1408${"text":"Для некоторых стран доступно пополнение кошелька с карт, однако России в данном списке нет. Адекватный перевод на русский язык некоторых разделов также отсутствует, что усложняет работу с системой. Для получения полного доступа требуется верификация личности – еще один недостаток платформы CoinPayments.","html":"Для некоторых стран доступно пополнение кошелька с карт, однако России в данном списке нет. Адекватный перевод на русский язык некоторых разделов также отсутствует, что усложняет работу с системой. Для получения полного доступа требуется верификация личности – еще один недостаток платформы CoinPayments."}$b1408$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

