INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 36, 'paragraph',
       $b1413${"text":"Относительно молодой «горячий» кошелек, появившийся в 2018 году. Проект обладает собственным служебным токеном ENJ, с помощью которого можно покупать цифровые активы, а также совершать обмены. Enjin Wallet работает с ключевыми сетями, включая ERC-20 и BTC. Инструмент поддерживает NFT, а также обладает собственным маркетплейсом. Кошелек полностью анонимный, безопасность находится на высоком уровне, однако исходный код закрыт.","html":"Относительно молодой «горячий» кошелек, появившийся в 2018 году. Проект обладает собственным служебным токеном ENJ, с помощью которого можно покупать цифровые активы, а также совершать обмены. Enjin Wallet работает с ключевыми сетями, включая ERC-20 и BTC. Инструмент поддерживает NFT, а также обладает собственным маркетплейсом. Кошелек полностью анонимный, безопасность находится на высоком уровне, однако исходный код закрыт."}$b1413$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 37, 'paragraph',
       $b1414${"text":"Стейкинг отсутствует, как и прямое пополнение с карты. Вместо десктопной и браузерной версии разработчики предлагают пользоваться исключительно мобильными устройствами, что удобно далеко не всегда. Зато есть дополнительные функции (трекер курса, создание неограниченного числа кошельков), а также перевод на многие языки, включая русский.","html":"Стейкинг отсутствует, как и прямое пополнение с карты. Вместо десктопной и браузерной версии разработчики предлагают пользоваться исключительно мобильными устройствами, что удобно далеко не всегда. Зато есть дополнительные функции (трекер курса, создание неограниченного числа кошельков), а также перевод на многие языки, включая русский."}$b1414$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

