INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 42, 'paragraph',
       $b1419${"text":"В качестве альтернативы Metamask для работы с сетью Ethereum можно использовать аналог – «горячий» кошелек MyEtherWallet. Разобраться с функционалом инструмента достаточно просто, даже несмотря на то, что далеко не все разделы приложения переведены на русский язык. Зато есть поддержка большинства популярных платформ как для мобильных устройств, так и настольных ПК.","html":"В качестве альтернативы Metamask для работы с сетью Ethereum можно использовать аналог – «горячий» кошелек MyEtherWallet. Разобраться с функционалом инструмента достаточно просто, даже несмотря на то, что далеко не все разделы приложения переведены на русский язык. Зато есть поддержка большинства популярных платформ как для мобильных устройств, так и настольных ПК."}$b1419$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 43, 'paragraph',
       $b1420${"text":"Помимо сети Ethereum кошелек MyEtherWallet работает с рядом других блокчейнов, включая BNB, ETC и тестовые форматы. Наличие встроенного обменника позволяет совершать внутренние транзакции, а ручное управление комиссиями помогает самостоятельно регулировать скорость совершения перевода. MyEtherWallet обладает хорошей репутацией и высокой степенью защиты, что позволяет навязать конкурентную борьбу Metamask.","html":"Помимо сети Ethereum кошелек MyEtherWallet работает с рядом других блокчейнов, включая BNB, ETC и тестовые форматы. Наличие встроенного обменника позволяет совершать внутренние транзакции, а ручное управление комиссиями помогает самостоятельно регулировать скорость совершения перевода. MyEtherWallet обладает хорошей репутацией и высокой степенью защиты, что позволяет навязать конкурентную борьбу Metamask."}$b1420$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

