INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 46, 'pros_cons',
       $b1423${"pros":["Действенный конкурент Metamask с аналогичным функционалом;","Множество разнообразных вариантов использования – мобильные приложения, браузеры, расширения;","Поддержка аппаратных кошельков (например, Trezor и Ledger);","Поддержка NFT и DeFi;","Ручное управление комиссиями;","Встроенный обменник;","Участие в ICO;","Покупка токенов при помощи банковской карты;","Высокая степень безопасности."],"cons":["Ограниченный набор сетей (например, нет BTC);","Сложности с восстановлением кошелька при утере доступа;","Не весь функционал переведен на русский язык."]}$b1423$::jsonb,
