INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 48, 'paragraph',
       $b1425${"text":"Кошелек Exodus появился на свет в 2016 году: на текущий момент это инструмент, обладающий базовым функционалом, которого достаточно для хранения активов и совершения обменов. Здесь нет ни поддержки NFT, ни функции стейкинга, ни каких-либо других опций, расширяющих возможности кошелька. Ключевая концепция Exodus – простота и легкая эксплуатация даже начинающими пользователями: с этой задачей кошелек успешно справляется.","html":"Кошелек Exodus появился на свет в 2016 году: на текущий момент это инструмент, обладающий базовым функционалом, которого достаточно для хранения активов и совершения обменов. Здесь нет ни поддержки NFT, ни функции стейкинга, ни каких-либо других опций, расширяющих возможности кошелька. Ключевая концепция Exodus – простота и легкая эксплуатация даже начинающими пользователями: с этой задачей кошелек успешно справляется."}$b1425$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 49, 'paragraph',
       $b1426${"text":"Есть ощутимые недостатки, например, необходимость пополнения кошелька для получения возможности сохранения собственной seed-фразы. Кроме того, пользователи Экседеса сталкиваются с высокими комиссиями и уязвимостями в системе безопасности, что отталкивает многих потенциальных криптоэнтузиастов.","html":"Есть ощутимые недостатки, например, необходимость пополнения кошелька для получения возможности сохранения собственной seed-фразы. Кроме того, пользователи Экседеса сталкиваются с высокими комиссиями и уязвимостями в системе безопасности, что отталкивает многих потенциальных криптоэнтузиастов."}$b1426$::jsonb,
