INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 54, 'paragraph',
       $b1431${"text":"Один из старейших «горячих» кошельков, работающий с 2011 года. По числу пользователей Blockchain Wallet сопоставим с лидерами нашего рейтинга – платформами Metamask и Trust Wallet, а в качестве поддержки выступает биржа Blockchain.com. К числу недостатков можно отнести ограниченное количество монет, отсутствие «настольной» версии, а также хранение приватных ключей на стороне самого кошелька.","html":"Один из старейших «горячих» кошельков, работающий с 2011 года. По числу пользователей Blockchain Wallet сопоставим с лидерами нашего рейтинга – платформами Metamask и Trust Wallet, а в качестве поддержки выступает биржа Blockchain.com. К числу недостатков можно отнести ограниченное количество монет, отсутствие «настольной» версии, а также хранение приватных ключей на стороне самого кошелька."}$b1431$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 55, 'paragraph',
       $b1432${"text":"Если пользователь планирует получить полный доступ ко всем инструментам кошелька Blockchain Wallet, придется пройти полноценную верификацию личности, что противоречит требованиям конфиденциальности многих пользователей. Зато кошелек обладает простым и понятным интерфейсом (в том числе на русском языке), обменником, фиатным счетом и высокой степенью безопасности.","html":"Если пользователь планирует получить полный доступ ко всем инструментам кошелька Blockchain Wallet, придется пройти полноценную верификацию личности, что противоречит требованиям конфиденциальности многих пользователей. Зато кошелек обладает простым и понятным интерфейсом (в том числе на русском языке), обменником, фиатным счетом и высокой степенью безопасности."}$b1432$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

