INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 60, 'paragraph',
       $b1437${"text":"Кошелек Coinbase Wallet является разработкой одноименной биржи, которая хорошо знакома владельцам цифровых активов со всего мира. Правда, сама биржа некоторое время назад отказалась от взаимодействия с российскими пользователями, однако на сегодняшний день нет никаких ограничений для работы именно с «горячим» кошельком Coinbase Wallet. Перспективы дальнейшего взаимодействия остаются загадкой, поэтому пользователи СНГ самостоятельно принимают решение о работе на указанной платформе.","html":"Кошелек Coinbase Wallet является разработкой одноименной биржи, которая хорошо знакома владельцам цифровых активов со всего мира. Правда, сама биржа некоторое время назад отказалась от взаимодействия с российскими пользователями, однако на сегодняшний день нет никаких ограничений для работы именно с «горячим» кошельком Coinbase Wallet. Перспективы дальнейшего взаимодействия остаются загадкой, поэтому пользователи СНГ самостоятельно принимают решение о работе на указанной платформе."}$b1437$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 61, 'paragraph',
       $b1438${"text":"Рассматривая сильные стороны кошелька Coinbase, можно отметить защищенность активов, наличие множества инструментов (стейкинг, DApps, интеграция с маркетплейсами, работа с NFT). А еще можно отправлять токены внутри экосистемы без указания адреса кошелька получателя – для этого достаточно знать лишь никнейм пользователя в Coinbase Wallet.","html":"Рассматривая сильные стороны кошелька Coinbase, можно отметить защищенность активов, наличие множества инструментов (стейкинг, DApps, интеграция с маркетплейсами, работа с NFT). А еще можно отправлять токены внутри экосистемы без указания адреса кошелька получателя – для этого достаточно знать лишь никнейм пользователя в Coinbase Wallet."}$b1438$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

