INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 66, 'paragraph',
       $b1443${"text":"«Горячий» кошелек Phantom работает в сети Solana – это наиболее популярная платформа для совершения транзакций в данном блокчейне и работе с профильными NFT-активами. Разработка отличается наличием стейкинга, функцией обмена активов, а также возможностью пополнения с банковской карты через систему Moonpay.","html":"«Горячий» кошелек Phantom работает в сети Solana – это наиболее популярная платформа для совершения транзакций в данном блокчейне и работе с профильными NFT-активами. Разработка отличается наличием стейкинга, функцией обмена активов, а также возможностью пополнения с банковской карты через систему Moonpay."}$b1443$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 67, 'paragraph',
       $b1444${"text":"Кошелек Фантом поддерживается известными фондами, а за безопасность активов отвечает некастодиальный формат функционирования. Помимо всего прочего, Phantom поддерживает кошельки Ledger, а биометрическая аутентификация дополняет систему безопасности. По мнению большинства криптоэнтузиастов, это лучший кошелек для работы в сети Solana.","html":"Кошелек Фантом поддерживается известными фондами, а за безопасность активов отвечает некастодиальный формат функционирования. Помимо всего прочего, Phantom поддерживает кошельки Ledger, а биометрическая аутентификация дополняет систему безопасности. По мнению большинства криптоэнтузиастов, это лучший кошелек для работы в сети Solana."}$b1444$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

