SELECT a.id, 70, 'pros_cons',
       $b1447${"pros":["Максимально простая и удобная работа в сети Solana;","Функция стейкинга SOL;","Обмен токенов внутри приложения;","Поддержка NFT;","Пополнение активов с карты;","Работа на мобильных приложениях и настольных ОС;","Встроенный браузер упрощает работу пользователя;","Поддержка русского языка в приложении;","Высокая степень защиты активов;","Поддержка холодных кошельков фирмы Ledger;","Поддержка DApps."],"cons":["Ограниченный набор монет для работы – ориентация на SOL;","Нет русского языка на официальном сайте;","Работа на настольных операционных системах осуществляется только через расширение браузера."]}$b1447$::jsonb,
