INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 72, 'paragraph',
       $b1449${"text":"Одним из ключевых конкурентов Metamask является разработка Trust Wallet, которая несмотря на более широкие функциональные возможности пользуется несколько меньшей популярностью у криптоэнтузиастов. Здесь есть поддержка BTC и SOL, а также функция стейкинга, позволяющая зарабатывать, отправляя монеты в специализированные хранилища.","html":"Одним из ключевых конкурентов Metamask является разработка Trust Wallet, которая несмотря на более широкие функциональные возможности пользуется несколько меньшей популярностью у криптоэнтузиастов. Здесь есть поддержка BTC и SOL, а также функция стейкинга, позволяющая зарабатывать, отправляя монеты в специализированные хранилища."}$b1449$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 73, 'paragraph',
       $b1450${"text":"С точки зрения безопасности «горячий» кошелек Trust Wallet предлагает более впечатляющие условия работы – приватные ключи хранятся на стороне пользователя, а не на серверах разработчика. Это позволяет пользователю самостоятельно записать seed-фразу и хранить ее в надежном месте.","html":"С точки зрения безопасности «горячий» кошелек Trust Wallet предлагает более впечатляющие условия работы – приватные ключи хранятся на стороне пользователя, а не на серверах разработчика. Это позволяет пользователю самостоятельно записать seed-фразу и хранить ее в надежном месте."}$b1450$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

