INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 78, 'paragraph',
       $b1455${"text":"Один из наиболее известных «горячих» кошельков, объединяющий несколько десятков миллионов пользователей по всему миру. Разработку одинаково удобно использовать как на мобильных устройствах, так и настольных ПК за счет расширений для популярных браузеров. Кошелек Metamask поддерживает популярные сети, включая экспериментальные форматы, что позволяет пользователям участвовать в тестировании новых платформ.","html":"Один из наиболее известных «горячих» кошельков, объединяющий несколько десятков миллионов пользователей по всему миру. Разработку одинаково удобно использовать как на мобильных устройствах, так и настольных ПК за счет расширений для популярных браузеров. Кошелек Metamask поддерживает популярные сети, включая экспериментальные форматы, что позволяет пользователям участвовать в тестировании новых платформ."}$b1455$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 79, 'paragraph',
       $b1456${"text":"Существенный недостаток один – это отсутствие совместимости с BTC и SOL. Проще говоря, работать с этими криптовалютами не получится, так как Metamask поддерживает только Ethereum и EVM-совместимые сети. Для использования Биткоина, Соланы и ряда других монет придется выбирать альтернативы.","html":"Существенный недостаток один – это отсутствие совместимости с BTC и SOL. Проще говоря, работать с этими криптовалютами не получится, так как Metamask поддерживает только Ethereum и EVM-совместимые сети. Для использования Биткоина, Соланы и ряда других монет придется выбирать альтернативы."}$b1456$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'kakoj-koshelek-dlya-kriptovalyuty-vybrat-10-luchshih-goryachih-hranilishh';

