INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 84, 'paragraph',
       $b1461${"text":"Горячие кошельки – отличный выбор для повседневного использования, быстрых переводов, торговли и Web3-активности. Они удобны, доступны и функциональны, особенно для тех, кто активно работает с криптовалютами.","html":"Горячие кошельки – отличный выбор для повседневного использования, быстрых переводов, торговли и Web3-активности. Они удобны, доступны и функциональны, особенно для тех, кто активно работает с криптовалютами."}$b1461$::jsonb,
