INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 85, 'paragraph',
       $b1462${"text":"Однако для хранения крупных сумм стоит рассматривать комбинированную стратегию: горячий кошелек – для повседневных операций, а холодный – для сбережений.","html":"Однако для хранения крупных сумм стоит рассматривать комбинированную стратегию: горячий кошелек – для повседневных операций, а холодный – для сбережений."}$b1462$::jsonb,
