INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 86, 'paragraph',
       $b1463${"text":"Идеальный подход: разделение риска и грамотное управление безопасностью. Только так можно воспользоваться преимуществами цифровых активов без страха потери средств.","html":"Идеальный подход: разделение риска и грамотное управление безопасностью. Только так можно воспользоваться преимуществами цифровых активов без страха потери средств."}$b1463$::jsonb,
