INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 2, 'paragraph',
       $b1465${"text":"Криптовалюта, как и любая другая ценность, требует надежного хранения. Если банковские счета защищены системой из паролей, SMS и регуляций, то криптовалюты – полностью под ответственностью владельца. Здесь нет «службы поддержки», которая поможет вернуть доступ к активам. Поэтому вопрос безопасности выходит на первый план.","html":"Криптовалюта, как и любая другая ценность, требует надежного хранения. Если банковские счета защищены системой из паролей, SMS и регуляций, то криптовалюты – полностью под ответственностью владельца. Здесь нет «службы поддержки», которая поможет вернуть доступ к активам. Поэтому вопрос безопасности выходит на первый план."}$b1465$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 3, 'paragraph',
       $b1466${"text":"Одним из самых надежных способов хранения криптовалют являются холодные кошельки. Эта статья поможет разобраться, что это такое, зачем они нужны, как правильно выбрать холодный кошелек, какие тонкости стоит учесть и как выглядит ТОП-10 лучших холодных кошельков для хранения криптовалют.","html":"Одним из самых надежных способов хранения криптовалют являются холодные кошельки. Эта статья поможет разобраться, что это такое, зачем они нужны, как правильно выбрать холодный кошелек, какие тонкости стоит учесть и как выглядит ТОП-10 лучших холодных кошельков для хранения криптовалют."}$b1466$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

