INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 6, 'paragraph',
       $b1469${"text":"Холодный кошелек (cold wallet) – это способ хранения криптовалют, при котором приватные ключи пользователя никогда не взаимодействуют напрямую с интернетом. Это ключевое отличие от горячих кошельков (hot wallets), которые всегда подключены к сети и потому потенциально уязвимы.","html":"Холодный кошелек (cold wallet) – это способ хранения криптовалют, при котором приватные ключи пользователя никогда не взаимодействуют напрямую с интернетом. Это ключевое отличие от горячих кошельков (hot wallets), которые всегда подключены к сети и потому потенциально уязвимы."}$b1469$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

