INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 9, 'paragraph',
       $b1472${"text":"Пример: у вас есть 2 BTC, которые вы не собираетесь использовать в ближайшие месяцы. Лучше всего их не держать на бирже или онлайн-кошельке, а переместить на холодный кошелек – будь то аппаратное устройство или даже бумажный ключ.","html":"Пример: у вас есть 2 BTC, которые вы не собираетесь использовать в ближайшие месяцы. Лучше всего их не держать на бирже или онлайн-кошельке, а переместить на холодный кошелек – будь то аппаратное устройство или даже бумажный ключ."}$b1472$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

