INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 12, 'rich_list',
       $b1475${"ordered":false,"items":[{"title":"Аппаратные кошельки (Hardware Wallets)","text":"Устройства, которые хранят приватные ключи в изолированной среде. Самые популярные производители: Ledger, Trezor, SafePal. Плюсы: высокая степень защиты, физический контроль у пользователя, поддержка многих монет и токенов. Минусы: стоит определенных денег, требует навыков обращения, можно потерять или повредить устройство;"},{"title":"Бумажные кошельки (Paper Wallets)","text":"Физически распечатанный лист с приватным и публичным ключом. Хранятся в сейфе или другом защищенном месте. Плюсы: бесплатный способ хранения, отсутствие цифровых следов. Минусы: легко повредить или потерять, неудобство использования, не поддерживает современные токены и стандарты;"},{"title":"Офлайн-компьютеры и флеш-носители","text":"Можно создать кошелек на полностью изолированном компьютере и хранить ключи на USB-накопителе, не подключенном к сети. Подходит для продвинутых пользователей, кто хочет кастомизировать безопасность."}]}$b1475$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

