INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 15, 'rich_list',
       $b1478${"ordered":false,"items":[{"title":"Seed-фраза – все или ничего","text":"Холодный кошелек создает seed-фразу (чаще всего 12–24 слова). Это главный ключ ко всем вашим криптовалютам. Потеряли фразу – потеряли средства. Храните ее физически, в нескольких местах, и не фотографируйте на телефон;"},{"title":"Проверяйте оригинальность устройства","text":"Покупать аппаратные кошельки нужно только у официальных поставщиков. В сети были случаи продажи «переупакованных» Ledger и Trezor с вредоносным ПО;"},{"title":"Защита от физического доступа","text":"Самый надежный кошелек бесполезен, если его украдут с вашим PIN-кодом или seed-фразой. Храните кошелек в безопасном месте, например, в сейфе;"},{"title":"Регулярные обновления прошивки","text":"Современные аппаратные кошельки требуют обновлений для защиты от новых уязвимостей. Не игнорируйте эти уведомления."}]}$b1478$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

