INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 20, 'paragraph',
       $b1483${"text":"Самый большой по размерам кошелек нашего рейтинга – холодное хранилище Ellipal Titan родом из Гонконга. Впрочем, Титан в названии олицетворяет не только габариты устройства, но и его функциональные возможности – здесь есть практически все для удобной и безопасной работы с цифровыми активами. Ключевая особенность кошелька – полное отсутствие классических вариантов соединения (нет ни USB, ни Wi-Fi, ни Bluetooth, ни NFC). Вся работа строится на основе QR-кодов, которые можно считывать как самим устройством, так и с его дисплея при помощи мобильного телефона.","html":"Самый большой по размерам кошелек нашего рейтинга – холодное хранилище Ellipal Titan родом из Гонконга. Впрочем, Титан в названии олицетворяет не только габариты устройства, но и его функциональные возможности – здесь есть практически все для удобной и безопасной работы с цифровыми активами. Ключевая особенность кошелька – полное отсутствие классических вариантов соединения (нет ни USB, ни Wi-Fi, ни Bluetooth, ни NFC). Вся работа строится на основе QR-кодов, которые можно считывать как самим устройством, так и с его дисплея при помощи мобильного телефона."}$b1483$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 21, 'paragraph',
       $b1484${"text":"Ellipal Titan поддерживает большое количество криптовалют (более 10 000) и хранит NFT. За безопасность отвечают стандартные настройки и уже упомянутая выше система использования QR-кодов. Стоимость устройства высокая, однако это оправдано технологической начинкой и возможностями кошелька.","html":"Ellipal Titan поддерживает большое количество криптовалют (более 10 000) и хранит NFT. За безопасность отвечают стандартные настройки и уже упомянутая выше система использования QR-кодов. Стоимость устройства высокая, однако это оправдано технологической начинкой и возможностями кошелька."}$b1484$::jsonb,
