INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 26, 'paragraph',
       $b1489${"text":"Холодный кошелек SecuX V20 не настолько популярен, как продукция Ledger, Trezor или SafePal, однако это весьма достойный инструмент тайваньского производителя. С визуальной точки зрения девайс выглядит ярко и респектабельно – здесь есть большой цветной дисплей и задняя крышка из алюминия. Да и сама по себе форма кошелька весьма необычна.","html":"Холодный кошелек SecuX V20 не настолько популярен, как продукция Ledger, Trezor или SafePal, однако это весьма достойный инструмент тайваньского производителя. С визуальной точки зрения девайс выглядит ярко и респектабельно – здесь есть большой цветной дисплей и задняя крышка из алюминия. Да и сама по себе форма кошелька весьма необычна."}$b1489$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 27, 'paragraph',
       $b1490${"text":"Еще больше интересного предлагает начинка SecuX: улучшенная безопасность хранения активов, большое число поддерживаемых блокчейнов и монет, взаимодействие с NFT, емкий аккумулятор, поддержка Bluetooth-соединения, а также хранение до 500 адресов для работы. Стоимость SecuX V20 выше среднего рыночного значения, но это вполне оправдано: внешний вид и функционал холодного кошелька вызывают уважение. Если вас не отпугивает далеко не самый известный производитель, покупка выглядит оправданной.","html":"Еще больше интересного предлагает начинка SecuX: улучшенная безопасность хранения активов, большое число поддерживаемых блокчейнов и монет, взаимодействие с NFT, емкий аккумулятор, поддержка Bluetooth-соединения, а также хранение до 500 адресов для работы. Стоимость SecuX V20 выше среднего рыночного значения, но это вполне оправдано: внешний вид и функционал холодного кошелька вызывают уважение. Если вас не отпугивает далеко не самый известный производитель, покупка выглядит оправданной."}$b1490$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

