INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 32, 'paragraph',
       $b1495${"text":"Швейцарская разработка – холодный кошелек KeepKey, являющийся альтернативой популярных моделей от Ledger и Trezor. На фоне конкурентов этот девайс отличается стильным внешним видом – устройство выглядит необычно и респектабельно (хотя кому-то корпус может показаться излишне громоздким). Здесь есть несколько форматов защиты (включая PIN-код и функцию seed-восстановления), а вот с точки зрения числа криптовалют производитель явно подкачал – KeepKey работает лишь с 40 токенами.","html":"Швейцарская разработка – холодный кошелек KeepKey, являющийся альтернативой популярных моделей от Ledger и Trezor. На фоне конкурентов этот девайс отличается стильным внешним видом – устройство выглядит необычно и респектабельно (хотя кому-то корпус может показаться излишне громоздким). Здесь есть несколько форматов защиты (включая PIN-код и функцию seed-восстановления), а вот с точки зрения числа криптовалют производитель явно подкачал – KeepKey работает лишь с 40 токенами."}$b1495$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 33, 'paragraph',
       $b1496${"text":"На корпусе кошелька есть только одна кнопка – это включение и выключение устройства. Все остальные действия производятся на мобильном телефоне (здесь снова есть ограничения по работе с iPhone).","html":"На корпусе кошелька есть только одна кнопка – это включение и выключение устройства. Все остальные действия производятся на мобильном телефоне (здесь снова есть ограничения по работе с iPhone)."}$b1496$::jsonb,
