INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 38, 'paragraph',
       $b1501${"text":"Создатели Tangem Wallet приняли решение инновационным образом подойти к политике безопасности при работе с холодными хранилищами. Здесь нет дисплеев, кнопок, проводов, а также seed-фраз. Кошелек представляет собой карту и приложение на телефон: связь осуществляется при помощи NFC-модуля. Если вы потеряете телефон, без наличия карты никто не сможет воспользоваться счетом. Если утеряна сама карта, то без телефона также нет доступа к счету (доступ восстанавливается путем приобретения еще одной карты). Если нет доступа и к карте, и к телефону, препятствием для злоумышленника станет пароль.","html":"Создатели Tangem Wallet приняли решение инновационным образом подойти к политике безопасности при работе с холодными хранилищами. Здесь нет дисплеев, кнопок, проводов, а также seed-фраз. Кошелек представляет собой карту и приложение на телефон: связь осуществляется при помощи NFC-модуля. Если вы потеряете телефон, без наличия карты никто не сможет воспользоваться счетом. Если утеряна сама карта, то без телефона также нет доступа к счету (доступ восстанавливается путем приобретения еще одной карты). Если нет доступа и к карте, и к телефону, препятствием для злоумышленника станет пароль."}$b1501$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 39, 'paragraph',
       $b1502${"text":"Согласно статистике, основная проблема криптоэнтузиастов при работе с холодными кошельками – потеря seed-фразы. Tangem Wallet позволяет решить данный вопрос, предлагая совершенно иной принцип работы своего девайса. Правда, для организации работы всего комплекса потребуется купить две (а лучше три) карты, что увеличивает бюджет на организацию холодного хранилища.","html":"Согласно статистике, основная проблема криптоэнтузиастов при работе с холодными кошельками – потеря seed-фразы. Tangem Wallet позволяет решить данный вопрос, предлагая совершенно иной принцип работы своего девайса. Правда, для организации работы всего комплекса потребуется купить две (а лучше три) карты, что увеличивает бюджет на организацию холодного хранилища."}$b1502$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

