INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 44, 'paragraph',
       $b1507${"text":"Самая популярная на сегодняшний день модель французского производителя Ledger, да и всего мира холодных кошельков в целом. Являясь предшественником Ledger Nano S, устройство позволяет хранить несколько тысяч наименований криптовалют. С памятью также все в порядке: техническая начинка допускает установку до сотни приложений, чего более чем достаточно для комфортной работы с кошельком.","html":"Самая популярная на сегодняшний день модель французского производителя Ledger, да и всего мира холодных кошельков в целом. Являясь предшественником Ledger Nano S, устройство позволяет хранить несколько тысяч наименований криптовалют. С памятью также все в порядке: техническая начинка допускает установку до сотни приложений, чего более чем достаточно для комфортной работы с кошельком."}$b1507$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 45, 'paragraph',
       $b1508${"text":"Девайс оснащен аккумулятором (до 8 часов работы), возможна работа с NFT и DeFi. Что же касается безопасности, Ledger Nano X способен похвастаться базовым пакетом шифрования, а также дополнительными инструментами. Среди недостатков можно выделить маленький дисплей и достаточно высокую стоимость для устройств такого класса – есть множество более дешевых аналогов от не менее именитых производителей.","html":"Девайс оснащен аккумулятором (до 8 часов работы), возможна работа с NFT и DeFi. Что же касается безопасности, Ledger Nano X способен похвастаться базовым пакетом шифрования, а также дополнительными инструментами. Среди недостатков можно выделить маленький дисплей и достаточно высокую стоимость для устройств такого класса – есть множество более дешевых аналогов от не менее именитых производителей."}$b1508$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

