INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 50, 'paragraph',
       $b1513${"text":"Улучшенная версия Ledger Nano S предлагает пользователю более внушительный объем памяти, что позволяет решить ключевую проблему базовой модели – невозможность нормальной установки сторонних приложений. Также несколько изменился размер корпуса, система подключения (Type-C вместо Micro-USB) и габариты дисплея. На этом все отличия между двумя указанными версиями заканчиваются.","html":"Улучшенная версия Ledger Nano S предлагает пользователю более внушительный объем памяти, что позволяет решить ключевую проблему базовой модели – невозможность нормальной установки сторонних приложений. Также несколько изменился размер корпуса, система подключения (Type-C вместо Micro-USB) и габариты дисплея. На этом все отличия между двумя указанными версиями заканчиваются."}$b1513$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 51, 'paragraph',
       $b1514${"text":"Ledger Nano S все еще можно купить в официальном магазине французского бренда. Это немаловажное преимущество, так как приобретение холодных кошельков в сомнительных маркетплейсах всегда сопряжено с риском взлома и кражи ваших активов.","html":"Ledger Nano S все еще можно купить в официальном магазине французского бренда. Это немаловажное преимущество, так как приобретение холодных кошельков в сомнительных маркетплейсах всегда сопряжено с риском взлома и кражи ваших активов."}$b1514$::jsonb,
