INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 56, 'paragraph',
       $b1519${"text":"Холодный кошелек от французского производителя Ledger. Это старейшая модель бренда, которая уже не продается в официальном магазине Ledger, однако многие холдеры криптовалют все еще активно используют девайс несмотря на его моральное устаревание. Среди слабых сторон можно назвать маленький объем памяти, совместимость далеко не со всеми платформами, а также не самую впечатляющую надежность. Срок службы такого решения составляет 3–5 лет, в зависимости от интенсивности использования.","html":"Холодный кошелек от французского производителя Ledger. Это старейшая модель бренда, которая уже не продается в официальном магазине Ledger, однако многие холдеры криптовалют все еще активно используют девайс несмотря на его моральное устаревание. Среди слабых сторон можно назвать маленький объем памяти, совместимость далеко не со всеми платформами, а также не самую впечатляющую надежность. Срок службы такого решения составляет 3–5 лет, в зависимости от интенсивности использования."}$b1519$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 57, 'paragraph',
       $b1520${"text":"Среди преимуществ можно отметить простоту эксплуатации, небольшую стоимость и удобное приложение для настольных операционных систем. Кстати, в Ledger Nano S нет поддержки телефонов iPhone, а сложности с приобретением могут стать причиной покупки кошелька у злоумышленников – все же рекомендуется выбирать официальные магазины производителя для девайсов подобного рода.","html":"Среди преимуществ можно отметить простоту эксплуатации, небольшую стоимость и удобное приложение для настольных операционных систем. Кстати, в Ledger Nano S нет поддержки телефонов iPhone, а сложности с приобретением могут стать причиной покупки кошелька у злоумышленников – все же рекомендуется выбирать официальные магазины производителя для девайсов подобного рода."}$b1520$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

