INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 62, 'paragraph',
       $b1525${"text":"Холодный кошелек SafePal S1 Hardware Wallet разработан при поддержке ведущей мировой криптобиржи Binance. С одной стороны это ощутимое преимущество, так как экосистеме Бинанса отведены ключевые позиции в сегменте цифрового золота – поддержка лидера всегда является преимуществом. Но с другой стороны в последнее время Binance имеет специфическое отношение к криптоэнтузиастам из России. Прямой угрозы для хранения токенов на кошельке SafePal S1 нет, однако если вас беспокоит данный фактор, лучше отдать предпочтение другому хранилищу.","html":"Холодный кошелек SafePal S1 Hardware Wallet разработан при поддержке ведущей мировой криптобиржи Binance. С одной стороны это ощутимое преимущество, так как экосистеме Бинанса отведены ключевые позиции в сегменте цифрового золота – поддержка лидера всегда является преимуществом. Но с другой стороны в последнее время Binance имеет специфическое отношение к криптоэнтузиастам из России. Прямой угрозы для хранения токенов на кошельке SafePal S1 нет, однако если вас беспокоит данный фактор, лучше отдать предпочтение другому хранилищу."}$b1525$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 63, 'paragraph',
       $b1526${"text":"Модель S1 отличается низкой стоимостью, наличием цветного дисплея, впечатляющим количеством поддерживаемых блокчейнов (более 30) и криптовалют (более 10 000). Надежность системы безопасности не подвергается сомнению, как и удобство эксплуатации Hardware Wallet. Работа с аппаратным кошельком осуществляется через мобильное приложение, а наличие перезаряжаемого аккумулятора позволяет работать SafePal S1 до 5 часов в автономном режиме.","html":"Модель S1 отличается низкой стоимостью, наличием цветного дисплея, впечатляющим количеством поддерживаемых блокчейнов (более 30) и криптовалют (более 10 000). Надежность системы безопасности не подвергается сомнению, как и удобство эксплуатации Hardware Wallet. Работа с аппаратным кошельком осуществляется через мобильное приложение, а наличие перезаряжаемого аккумулятора позволяет работать SafePal S1 до 5 часов в автономном режиме."}$b1526$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

