INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 68, 'paragraph',
       $b1531${"text":"Более совершенный вариант базового решения от чешского производителя Trezor. Расширенный список поддерживаемых блокчейнов и криптовалют, большой сенсорный дисплей, расширенные инструменты безопасности и все то же высокое качество от проверенного европейского бренда. Отпугнуть может лишь высокая стоимость, однако если вы заботитесь о сохранности актива и планируете хранить богатый портфель, Trezor Model T станет отличным вариантом холодного кошелька.","html":"Более совершенный вариант базового решения от чешского производителя Trezor. Расширенный список поддерживаемых блокчейнов и криптовалют, большой сенсорный дисплей, расширенные инструменты безопасности и все то же высокое качество от проверенного европейского бренда. Отпугнуть может лишь высокая стоимость, однако если вы заботитесь о сохранности актива и планируете хранить богатый портфель, Trezor Model T станет отличным вариантом холодного кошелька."}$b1531$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 69, 'paragraph',
       $b1532${"text":"Устройство дополнено менеджером паролей и системой безопасности Shamir Backup, а наличие слота для карты памяти MicroSD позволит хранить seed-фразу на этом носителе данных. Упаковка отличается надежностью и дополнительной защитой в виде голограммы – еще один элемент безопасности от чешского бренда.","html":"Устройство дополнено менеджером паролей и системой безопасности Shamir Backup, а наличие слота для карты памяти MicroSD позволит хранить seed-фразу на этом носителе данных. Упаковка отличается надежностью и дополнительной защитой в виде голограммы – еще один элемент безопасности от чешского бренда."}$b1532$::jsonb,
