INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 74, 'paragraph',
       $b1537${"text":"Один из самых недорогих холодных кошельков, отличающийся простотой и наличием базового сервиса. Здесь есть все необходимое для аккумуляции цифровых активов без лишнего функционала и переплат. Производителем является известный чешский бренд, который славится на весь мир качеством и надежностью своей продукции. Добавить к этому следует наличие небольшого дисплея, надежную упаковку и качественную систему защиты криптовалют.","html":"Один из самых недорогих холодных кошельков, отличающийся простотой и наличием базового сервиса. Здесь есть все необходимое для аккумуляции цифровых активов без лишнего функционала и переплат. Производителем является известный чешский бренд, который славится на весь мир качеством и надежностью своей продукции. Добавить к этому следует наличие небольшого дисплея, надежную упаковку и качественную систему защиты криптовалют."}$b1537$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshij-holodnyj-koshelek-dlya-kriptovalyuty-top-10';

