SELECT a.id, 75, 'paragraph',
       $b1538${"text":"Холодный кошелек Trezor Model One – это, своего рода, обязательный минимум для хранения цифрового золота вне биржи. Поддерживает основные токены и базовые блокчейны, однако для продвинутых пользователей и опытных криптоэнтузиастов функционала может оказаться недостаточно.","html":"Холодный кошелек Trezor Model One – это, своего рода, обязательный минимум для хранения цифрового золота вне биржи. Поддерживает основные токены и базовые блокчейны, однако для продвинутых пользователей и опытных криптоэнтузиастов функционала может оказаться недостаточно."}$b1538$::jsonb,
